CREATE TABLE acceptance_records (
    id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    text_value LONGTEXT,
    binary_value BLOB,
    numeric_value DECIMAL(38, 9),
    integer_value BIGINT,
    float_value DOUBLE,
    boolean_value BOOLEAN
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4;
INSERT INTO acceptance_records
    (text_value, binary_value, numeric_value, integer_value, float_value, boolean_value)
SELECT 'hello 世界 ''quoted'' \\ path\nline', X'00FF10205C0A',
       12345678901234567890.123456789, -9223372036854775000, 1.25, TRUE
FROM
    (SELECT 0 AS digit UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3
     UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7
     UNION ALL SELECT 8 UNION ALL SELECT 9) AS digits
CROSS JOIN
    (SELECT 0 UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3
     UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7
     UNION ALL SELECT 8 UNION ALL SELECT 9) AS tens
CROSS JOIN
    (SELECT 0 UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3
     UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7
     UNION ALL SELECT 8 UNION ALL SELECT 9) AS hundreds
CROSS JOIN
    (SELECT 0 UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3
     UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7
     UNION ALL SELECT 8 UNION ALL SELECT 9) AS thousands
CROSS JOIN
    (SELECT 0 UNION ALL SELECT 1) AS ten_thousands
LIMIT 12001;
